package io.github.jesterportfolio.hearth.combat;

import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static io.github.jesterportfolio.hearth.combat.CombatContent.*;
import static io.github.jesterportfolio.hearth.combat.CombatAttempt.*;

final class CombatHudTest {
    @Test void ownHealthFractionAndSharedBudgetAreReadOnlyAndScoped(){var f=new CombatAttemptTest.Fixture();var before=f.fight.snapshot();var hud=f.fight.hud(f.p,f.one,30,40);assertEquals(0.75f,hud.progress());assertTrue(hud.visible());assertTrue(hud.action().contains("공동 부활 남음: 2"));assertFalse(hud.toString().contains(f.q.playerId().toString()));assertEquals(before,f.fight.snapshot());assertThrows(IllegalStateException.class,()->f.fight.hud(f.p,new Object(),30,40));assertThrows(IllegalStateException.class,()->f.fight.hud(f.access.forVerifiedServerLink(UUID.randomUUID(),f.p.playerId()),f.one,30,40));}
    @Test void personalAndDisabledRevivalAreDistinct(){var f=new CombatAttemptTest.Fixture(CombatAttemptTest.content(Pool.PERSONAL,1,LocationMode.START),2);f.deadP();f.fight.revive(f.p,f.one,UUID.randomUUID(),"rescue");assertTrue(f.fight.hud(f.p,f.one,20,40).action().contains("개인 부활 남음: 0"));assertTrue(f.fight.hud(f.q,f.two,20,40).action().contains("개인 부활 남음: 1"));assertTrue(f.fight.hud(f.p,f.one,20,40).action().contains("부활 적용 대기"));
        var c=CombatAttemptTest.content(Pool.SHARED,2,LocationMode.START);var r=c.revival();var off=new CombatContent(c.id(),c.title(),20,2,3000,new Revival(false,r.condition(),r.pool(),r.limit(),r.healthFraction(),r.location(),r.fixed(),r.effects()));var g=new CombatAttemptTest.Fixture(off,1);assertTrue(g.fight.hud(g.p,g.one,20,20).action().contains("부활 불가"));}
    @Test void wipeHoldAndReturnProtectionTakePriorityOverCounts(){var f=new CombatAttemptTest.Fixture();f.deadP();assertTrue(f.fight.hud(f.p,f.one,40,40).action().contains("생존 동료 관전"));f.fight.disconnect(f.q,f.two,f.pose);assertTrue(f.fight.hud(f.p,f.one,40,40).action().startsWith("전투 일시정지"));var fresh=new Object();f.fight.reconnect(f.q,fresh);assertTrue(f.fight.hud(f.q,fresh,40,40).action().startsWith("복귀 위치 적용 대기"));f.fight.returned(f.q,fresh);assertTrue(f.fight.hud(f.q,fresh,40,40).action().startsWith("복귀 보호"));f.clock.addAndGet(3000);f.fight.poll();f.fight.died(f.q,fresh,f.pose);assertTrue(f.fight.hud(f.p,f.one,40,40).action().startsWith("전멸 대기"));f.fight.invalidate();assertTrue(f.fight.hud(f.p,f.one,40,40).action().startsWith("전투 처리 보류"));}
    @Test void terminalOutcomeHidesBossBarWithoutChangingPlayerState(){for(var outcome:Outcome.values()){if(outcome==Outcome.NONE)continue;var f=new CombatAttemptTest.Fixture();f.deadP();f.fight.finish(outcome);var before=f.fight.snapshot();var hud=f.fight.hud(f.p,f.one,0,40);assertFalse(hud.visible());assertTrue(hud.action().contains(CombatHud.outcome(outcome)));assertTrue(hud.notice().contains("사망 / 관전"));assertEquals(before,f.fight.snapshot());}}
    @Test void invalidHealthIsRejectedInsteadOfShowingFullOrNan(){var f=new CombatAttemptTest.Fixture();for(double health:new double[]{-1,41,Double.NaN,Double.POSITIVE_INFINITY})assertThrows(IllegalArgumentException.class,()->f.fight.hud(f.p,f.one,health,40));for(double maximum:new double[]{0,-1,Double.NaN,Double.POSITIVE_INFINITY})assertThrows(IllegalArgumentException.class,()->f.fight.hud(f.p,f.one,0,maximum));assertEquals(0,f.fight.hud(f.p,f.one,0,40).progress());}
    @Test void repeatedHealthUpdatesDoNotRepeatChatOrActionBarAndRefreshIsBounded(){var f=new CombatAttemptTest.Fixture();var delivery=new CombatHud.Delivery();var initial=f.fight.hud(f.p,f.one,40,40);assertEquals(new CombatHud.Update(true,true,true),delivery.next(initial,1));assertEquals(new CombatHud.Update(false,false,false),delivery.next(initial,2));var injured=f.fight.hud(f.p,f.one,20,40);assertEquals(new CombatHud.Update(true,false,false),delivery.next(injured,3));assertEquals(new CombatHud.Update(false,true,false),delivery.next(injured,21));f.deadP();assertEquals(new CombatHud.Update(false,true,true),delivery.next(f.fight.hud(f.p,f.one,20,40),22));assertFalse(delivery.next(f.fight.hud(f.p,f.one,20,40),23).notice());assertThrows(IllegalArgumentException.class,()->delivery.next(initial,-1));}
    @Test void terminalNoticeIsOnceAndDoesNotKeepOverwritingActionBar(){var f=new CombatAttemptTest.Fixture();var delivery=new CombatHud.Delivery();delivery.next(f.fight.hud(f.p,f.one,40,40),1);f.fight.victory();var closed=f.fight.hud(f.p,f.one,0,40);assertEquals(new CombatHud.Update(true,true,true),delivery.next(closed,2));assertEquals(new CombatHud.Update(false,false,false),delivery.next(closed,100));}
    @Test void helpOnlyExposesImplementedSelfCommands(){for(String line:List.of("/hearthcombat","/hearthcombat help","/hearthcombat status","/hearthcombat watch"))assertTrue(CombatHud.command(line));for(String line:List.of("/hearthcombat status other","/hearthcombat revive","/hearthcombat retry","/hearthcombat watch other"))assertFalse(CombatHud.command(line));assertTrue(CombatHud.help().stream().anyMatch(s->s.contains("재도전 투표는 아직")));}
}
